def create_existing_stock_alerts(apps, schema_editor):
    StockAlert = apps.get_model("inventory", "StockAlert")
    InventoryBalance = apps.get_model("inventory", "InventoryBalance")
    Product = apps.get_model("products", "Product")

    alerts = []

    # Products that already have an inventory balance.
    balances = (
        InventoryBalance.objects
        .filter(product__is_active=True)
        .select_related("product")
        .iterator()
    )

    for balance in balances:
        product = balance.product
        quantity = balance.quantity_on_hand

        should_alert = (
            quantity <= 0
            or (
                product.reorder_level > 0
                and quantity <= product.reorder_level
            )
        )

        if should_alert:
            alerts.append(
                StockAlert(
                    product_id=product.pk,
                    quantity_on_hand=quantity,
                    reorder_level=product.reorder_level,
                    is_read=False,
                )
            )

    # Active products without an inventory balance have zero stock.
    products_without_balance = (
        Product.objects
        .filter(
            is_active=True,
            inventory_balance__isnull=True,
        )
        .iterator()
    )

    for product in products_without_balance:
        alerts.append(
            StockAlert(
                product_id=product.pk,
                quantity_on_hand=0,
                reorder_level=product.reorder_level,
                is_read=False,
            )
        )

    StockAlert.objects.bulk_create(alerts, batch_size=500)


